"""Freeze owner-supplied-style test evidence, never real merchant performance.

The evaluator's expectations are kept outside the per-agent working directories.
No model/API calls, external writes, or real customer data in fixture preparation.
"""
import argparse, hashlib, io, json, pathlib, shutil, zipfile

HERE = pathlib.Path(__file__).resolve().parent

def write_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')

