def prepare(args):
    suite = json.loads(pathlib.Path(args.suite).read_text(encoding='utf-8'))
    root = pathlib.Path(args.out).resolve(); root.mkdir(parents=True, exist_ok=True)
    write_json(root/'suite.json', {**suite, 'status': 'frozen single-trial host-execution suite; results recorded separately', 'actual_protocol': {'auth': 'Existing Codex desktop session/sub-agents; no paid API calls', 'trials': 1, 'comparison': 'patched packs; targeted corrections rerun; no causal lift or all-three reliability claim', 'evidence': 'synthetic merchant fixture + dated public evidence if researched', 'tools': 'Desktop sub-agents; exact fresh/same-batch context recorded in dispatch.json. Shell/local artifacts + public research and subscription imagegen when appropriate; no commerce connector actions', 'quality_judge': 'root reviewer of actual outputs, separate from their generator; code checks for exact arithmetic. Not a human expert panel or blind baseline comparison.', 'cli_status': 'ChatGPT auth passed; CLI tool launch failed Windows registered-Core smoke test. CLI runner retained for other compatible hosts, not used for reported output benchmark.'}})
    only = set(args.only.split(',')) if args.only else None
    rows = []
    for task in suite['tasks']:
        if only and task['agent_id'] not in only: continue
        aid=task['agent_id']; dest=root/'cases'/aid
        if dest.exists():
            if args.resume and (root/'manifests'/f'{aid}.json').exists():
                old=json.loads((root/'manifests'/f'{aid}.json').read_text(encoding='utf-8'))
                rows.append({'agent_id':aid,'case':str(dest),'files':len(old['files'])})
                continue
            if not args.resume or any((dest/'output').glob('*')):raise SystemExit(f'Refusing to overwrite frozen case {dest}')
            # An interrupted preparation with no manifest and no generated work can
            # be completed. Existing frozen cases above are never rewritten.
        dest.mkdir(parents=True,exist_ok=True)
        zpath=pathlib.Path(args.packs)/f'{aid}.zip'
        archive=zpath.read_bytes()
        with zipfile.ZipFile(io.BytesIO(archive)) as z:
            for entry in z.infolist():
                parts=pathlib.PurePosixPath(entry.filename).parts
                if not parts or entry.is_dir(): continue
                if parts[0] == aid: parts=parts[1:]
                target=dest.joinpath(*parts).resolve()
                if not target.is_relative_to(dest.resolve()): raise ValueError('unsafe pack archive')
                target.parent.mkdir(parents=True,exist_ok=True); target.write_bytes(z.read(entry))
        evidence=dest/'evidence'; evidence.mkdir(exist_ok=True)
        for name,body in fixtures().items(): write_json(evidence/name,body)
        assets=evidence/'assets';assets.mkdir(exist_ok=True)
        (assets/'product.svg').write_text(SVG,encoding='utf-8')
        (assets/'product-page.html').write_text(HTML,encoding='utf-8')
        (assets/'product-section.liquid').write_text('<section><h1>{{ product.title | escape }}</h1><form action="/cart/add" method="post"><select name="id">{% for variant in product.variants %}<option value="{{ variant.id }}">{{ variant.title | escape }}</option>{% endfor %}</select><button type="submit">Add to cart</button></form></section>',encoding='utf-8')
        (dest/'output').mkdir(exist_ok=True)
        research = '\nThis request specifically concerns Allbirds. Ignore synthetic merchant metrics, product and brand records for all Allbirds claims. Research public primary sources and cite inspected URLs/dates; distinguish hypotheses from inspected findings.' if aid.startswith(('stuart-','rustam-')) else ''
        prompt = f'''You are carrying out a real output evaluation of the downloaded specialist pack in this working directory. Act as its agent for the user request below, read its AGENTS.md, METHOD.md and relevant toolbox/method/evidence. This is not a coding task to improve the agent. Do not inspect the parent repository, harness, other cases, graders, or previous results. Do not change instructions, tools or supplied evidence. context/ is editable working memory.\n\nUSER REQUEST:\n{task['request']}\n\nSUPPLIED MATERIAL:\nRead evidence/fixture-notice.json first. evidence/ contains the explicitly illustrative owner-style records, constraints, source IDs and editable local assets needed for the task. They are synthetic test data, not any real business performance or customer reviews. Use only the relevant files. All fixture records dated 2026-11-17 are intentionally current for this evaluation; public claims require dated source checks. {research}\n\nEXECUTION:\nFinish the requested work, not merely a plan for somebody to do it. Use local tools for calculations and meaningful artifact checks. Save requested native deliverables under output/ and write output/answer.md with the final user-facing response. Public web research is allowed; no emails, account writes, publishing, purchases, paid APIs, or new credentials. Use draft scope. Nobody will answer intake questions: state necessary assumptions and complete what can safely be completed. Missing photos/footage/connectors are genuine capability limits: produce useful honest feasible artifacts and specify exactly what remains blocked; never claim a visual was generated, rendered, inspected or a live action was performed if it was not. No exact output-length target: enough depth and specificity to be useful. Do not use another LLM/API.\n\nFinal response must link the artifacts you actually produced, show source-backed calculations/claims and relevant limits, and tell the owner the next concrete decision. Tools must operate inside this case except reading publicly accessible sources; do not install packages or modify shared settings.\n'''
        (dest/'request.txt').write_text(prompt,encoding='utf-8')
        files=[p for p in dest.rglob('*') if p.is_file()]
        manifest={str(p.relative_to(dest)).replace('\\','/'): hashlib.sha256(p.read_bytes()).hexdigest() for p in files}
        write_json(root/'manifests'/f'{aid}.json',{'agent_id':aid,'zip_sha256':hashlib.sha256(archive).hexdigest(),'files':manifest,'task':task})
        rows.append({'agent_id':aid,'case':str(dest),'files':len(manifest)})
    write_json(root/'prepared.json',rows)
    print(json.dumps({'cases':len(rows),'root':str(root)}))

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--suite',required=True);p.add_argument('--packs',required=True);p.add_argument('--out',required=True);p.add_argument('--only');p.add_argument('--resume',action='store_true');prepare(p.parse_args())
